 for(const [id,p] of Object.entries(stations)){if(!game.done.has(id)){rect(p.x-15,p.y-2,30,3,'#ffdf86');text('✦',p.x,p.y-8,14,'#ffe29a')}}
 adults.forEach(n=>{if(game.possessed===n.id)return;person(n.x,n.y,n.shirt,n.hair,n.apron);text(n.name,n.x,n.y+12,12,'#fff1d2')});
