}
function draw(){
 ctx.clearRect(0,0,W,H);drawRoom();drawCharacter();
 // little glints and a gentle ghost aura
 if(!game.possessed){ctx.globalAlpha=.22;rect(game.x-20,game.y-31,40,36,'#9bffe8');ctx.globalAlpha=1}
 const target=nearby();
 if(target){const p=target.point;text(target.label,p.x,p.y-26,13,'#fff3c9')}
}
function nearby(){
 if(!game.possessed){let best=null,dist=58;for(const n of adults){const d=Math.hypot(game.x-n.x,game.y-n.y);if(d<dist){best={kind:'adult',npc:n,point:n,label:`${n.name} · ${n.role}`};dist=d}}return best}
 let best=null,dist=55;
 for(const [id,p] of Object.entries(stations)){if(game.done.has(id))continue;const d=Math.hypot(game.x-p.x,game.y-p.y);if(d<dist){best={kind:'station',id,point:p,label:p.label};dist=d}}
 if(best)return best;
 for(const n of adults){if(n.id===game.possessed)continue;const d=Math.hypot(game.x-n.x,game.y-n.y);if(d<dist){best={kind:'adult',npc:n,point:n,label:`Swap to ${n.name}`};dist=d}}
 return best;
}
function say(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(game.toastTimer);game.toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function refreshHUD(){
 const count=3-game.done.size;
 document.getElementById('status').innerHTML=game.possessed?`✨ ${adults.find(n=>n.id===game.possessed).name's body<br><span class="sub">Borrowed with permission</span>`:`👻 Free spirit<br><span class="sub">${count} / 3 chores</span>`;
 document.getElementById('quest').innerHTML=`<b>TONIGHT'S PREP</b><br>${['stool','tea','table'].map(id=>`${game.done.has(id)?'☑':'□'} ${jobNames[id]}`).join('<br>')}`;
 document.getElementById('hint').innerHTML=game.possessed?`Walk to a glowing station and press <b>SPACE / ACTION</b>. Press <b>Q</b> to float free.`:`Find a grown-up who can help, then press <b>SPACE / ACTION</b>. Move with <b>WASD</b> / arrows.`;
}
function act(){
 if(!game.started)return;
 const target=nearby();
 if(!game.possessed){if(target&&target.kind==='adult'){game.possessed=target.npc.id;game.x=target.npc.x;game.y=target.npc.y;say(`${target.npc.name} lends you a hand. Let's help!`);refreshHUD()}else say('Float close to one of the grown-ups first.');return}
 if(target?.kind==='station'){
  const adult=adults.find(n=>n.id===game.possessed);
  if(target.id!==adult.job){say(`${adult.name} isn't sure how to do that job. Try another grown-up!`);return}
  game.done.add(target.id);say(`${adult.name} finished: ${jobNames[target.id]}!`);refreshHUD();
  if(game.done.size===3){setTimeout(()=>document.getElementById('ending').classList.remove('hide'),650)}return
 }
 if(target?.kind==='adult'){game.possessed=target.npc.id;game.x=target.npc.x;game.y=target.npc.y;say(`You gently swap to ${target.npc.name}'s borrowed skills.`);refreshHUD();return}
 say('Head toward the matching glowing station, or press Q to float free.');
}
function release(){if(game.possessed){const n=adults.find(a=>a.id===game.possessed);game.possessed=null;game.x=Math.max(24,Math.min(W-24,game.x+25));say(`Thanks, ${n.name}! You float free.`);refreshHUD()}}
function move(dt){if(!game.started)return;let dx=0,dy=0;if(keys.has('ArrowLeft')||keys.has('a'))dx--;if(keys.has('ArrowRight')||keys.has('d'))dx++;if(keys.has('ArrowUp')||keys.has('w'))dy--;if(keys.has('ArrowDown')||keys.has('s'))dy++;if(dx&&dy){dx*=.707;dy*=.707}if(dx||dy){game.x=Math.max(22,Math.min(W-22,game.x+dx*150*dt));game.y=Math.max(96,Math.min(H-28,game.y+dy*150*dt));game.walking+=dt*10;game.facing=dx<0?'left':dx>0?'right':dy<0?'up':'down'}}
let last=performance.now();function loop(now){const dt=Math.min(.04,(now-last)/1000);last=now;move(dt);draw();requestAnimationFrame(loop)}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key===' '?' ':e.key);if(e.key===' '||e.key==='Enter')act();if(e.key.toLowerCase()==='q')release()});window.addEventListener('keyup',e=>keys.delete(e.key===' '?' ':e.key));
const action=document.getElementById('action');action.addEventListener('pointerdown',e=>{e.preventDefault();act()});
document.querySelectorAll('[data-dir]').forEach(btn=>{const key={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[btn.dataset.dir];btn.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(key);btn.classList.add('down');btn.setPointerCapture(e.pointerId)});const stop=()=>{keys.delete(key);btn.classList.remove('down')};btn.addEventListener('pointerup',stop);btn.addEventListener('pointercancel',stop);btn.addEventListener('lostpointercapture',stop)});
document.getElementById('start').addEventListener('click',()=>{game.started=true;document.getElementById('intro').classList.add('hide');say('The grown-ups are ready to lend a hand!')});
document.getElementById('again').addEventListener('click',()=>location.reload());
refreshHUD();requestAnimationFrame(loop);
})();
</script>
</body>
</html>

